+import { stat } from 'node:fs/promises';
+import { resolve, relative, isAbsolute, extname } from 'node:path';
+import { fileURLToPath } from 'node:url';
+
+const DATA_DIR = resolve(fileURLToPath(new URL('./data/', import.meta.url)));
+
+const fileMetadataTool = {
+  name: 'file_metadata',
+  description:
+    'Return metadata (relative path, byte size, and lowercase extension) for a file under the workspace data directory. File contents are not exposed.',
+  inputSchema: {
+    type: 'object',
+    properties: {
+      path: {
+        type: 'string',
+        description: 'Relative path of the file within the data directory.',
+      },
+    },
+    required: ['path'],
+    additionalProperties: false,
+  },
+};
+
+const TOOLS = [fileMetadataTool];
+
+export async function listTools() {
+  return TOOLS;
+}
+
+function isInsideDataDir(absPath) {
+  const rel = relative(DATA_DIR, absPath);
+  // Reject anything that escapes the data directory (starts with '..') or
+  // lives on a different root (absolute relative path, e.g. another drive).
+  // The data directory itself (rel === '') and any descendant are allowed;
+  // non-files are rejected later by the isFile() check.
+  return !rel.startsWith('..') && !isAbsolute(rel);
+}
+
+export async function callTool(name, args = {}) {
+  if (name !== fileMetadataTool.name) {
+    throw new Error(`Unknown tool: ${name}`);
+  }
+
+  // Strict runtime validation mirroring the schema.
+  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
+    throw new Error('Invalid arguments: expected an object');
+  }
+  for (const key of Object.keys(args)) {
+    if (key !== 'path') {
+      throw new Error(`Unknown argument: ${key}`);
+    }
+  }
+  if (!('path' in args)) {
+    throw new Error('Missing required argument: path');
+  }
+  const inputPath = args.path;
+  if (typeof inputPath !== 'string' || inputPath.length === 0) {
+    throw new Error('path must be a non-empty string');
+  }
+
+  const absPath = resolve(DATA_DIR, inputPath);
+  if (!isInsideDataDir(absPath)) {
+    throw new Error('Path traversal not allowed');
+  }
+
+  let info;
+  try {
+    info = await stat(absPath);
+  } catch (error) {
+    if (error.code === 'ENOENT') {
+      throw new Error(`File not found: ${inputPath}`);
+    }
+    throw error;
+  }
+  if (!info.isFile()) {
+    throw new Error(`Not a file: ${inputPath}`);
+  }
+
+  const relPath = relative(DATA_DIR, absPath);
+  const size = info.size;
+  const extension = extname(absPath).toLowerCase();
+
+  return {
+    content: [
+      {
+        type: 'text',
+        text: `path: ${relPath}\nsize: ${size} bytes\nextension: ${extension}`,
+      },
+    ],
+  };
+}
